def clean(df):
    df = df.copy()
    # strip whitespace from text columns
    for col in ['Category', 'Region', 'Date', 'Product']:
        if col in df.columns:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix Region typos / out of range variants
    region_map = {'Suoth': 'South', 'Nort': 'North'}
    if 'Region' in df.columns:
        df['Region'] = df['Region'].replace(region_map)
    # ensure numeric types
    for col in ['Quantity', 'Price', 'Revenue', 'Order_ID']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix cross-column Revenue = Quantity * Price
    if all(c in df.columns for c in ['Quantity', 'Price', 'Revenue']):
        df['Revenue'] = df['Quantity'] * df['Price']
    # fix invalid dates
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    return df

def answer(df):
    # total revenue by region for Electronics
    if 'Category' not in df.columns or 'Region' not in df.columns or 'Revenue' not in df.columns:
        return {}
    d = df[df['Category'] == 'Electronics'].copy()
    d = d.dropna(subset=['Region'])
    # drop missing group keys and empty strings
    d = d[d['Region'].astype(str).str.strip() != '']
    grouped = d.groupby('Region')['Revenue'].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # convert numpy types to python int/float
        val = float(v)
        if val.is_integer():
            val = int(val)
        result[str(k)] = val
    return result
